// Turns the insert's outcome into the HTTP answer.
const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
if (r.run_id) return { json: { code: 202, body: { runId: r.run_id } } };
if (!r.job_found) return { json: { code: 404, body: { error: 'job_not_found' } } };
if (r.extraction_status !== 'done') return { json: { code: 422, body: { error: 'job_not_ready' } } };
if (!r.cv_ready) return { json: { code: 422, body: { error: 'base_cv_not_ready' } } };
// Ready, but no row: the job already has an active run.
return { json: { code: 409, body: { error: 'generation_in_progress' } } };

// Builds the answer. A generation error is shown only when it is one of the Generate workflow's own
// user-facing messages (grep "error" in generate-documents.json). Anything else may hold raw error
// text, so it is replaced by a fixed message.
const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
if (!r.found) return { json: { code: 404, body: { error: 'job_not_found' } } };
const FIXED = new Set([
  'The job was not found.',
  "The job's details have not been read yet.",
  "Your base CV isn't ready.",
  'Your base CV file could not be read; it will be tried again.',
  'The last attempt stopped before it finished; it will be tried again.',
  'Generation stopped and gave up after 3 attempts.',
  'Claude declined to write the documents.',
  'Claude declined to review the documents.',
  "Claude's answer was cut off (max_tokens).",
  "The writer's answer was not in the expected format.",
  "The reviewer's answer was not in the expected format.",
  "The writer's documents were not in the expected format.",
]);
const PATTERNS = [
  /^The request to Claude failed \((HTTP \d{3}|no response)\)\.$/,
  /^Claude stopped unexpectedly \(([a-z_]{1,40}|no stop reason)\)\.$/,
  /^The document checks could not run \((HTTP \d{3}|no response)\)\.$/,
];
const GENERIC = 'Something went wrong while generating. Try again.';
let generation = r.generation || null;
if (generation && generation.error != null) {
  const e = String(generation.error);
  generation = { ...generation, error: FIXED.has(e) || PATTERNS.some((p) => p.test(e)) ? e : GENERIC };
}
return { json: { code: 200, body: { job: r.job, generation, version: r.version || null } } };

const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
const status = typeof (($('POST api/jobs/status').first().json.body || {}).status) === 'string' ? $('POST api/jobs/status').first().json.body.status : '';
if (!r.valid) return { json: { code: 400, body: { error: 'bad_status' } } };
if (!r.found) return { json: { code: 404, body: { error: 'job_not_found' } } };
return { json: { code: 200, body: { status } } };

const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
const notes = ($('POST api/jobs/notes').first().json.body || {}).notes;
if (typeof notes !== 'string' || notes.indexOf(String.fromCharCode(0)) >= 0 || Array.from(notes).length > 4000) return { json: { code: 400, body: { error: 'bad_notes' } } };
if (!r.found) return { json: { code: 404, body: { error: 'job_not_found' } } };
return { json: { code: 200, body: { notes } } };

// Validates the query. Anything unexpected is a 400 before the database is touched.
const q = $json.query || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ok = typeof q.id === 'string' && UUID.test(q.id)
  && (q.doc === 'cv' || q.doc === 'cover_letter')
  && (q.format === 'docx' || q.format === 'pdf');
if (!ok) return { json: { ok: false, code: 400, body: { error: 'bad_request' } } };
return { json: { ok: true, id: q.id, doc: q.doc, format: q.format } };

// The worker request, the download file name and the response headers.
const req = $('Check download request').first().json;
const r = $json;
if (r.error) return { json: { render: false, code: 500, body: { error: 'server_error' } } };
if (!r.found) return { json: { render: false, code: 404, body: { error: 'job_not_found' } } };
if (!r.version) return { json: { render: false, code: 404, body: { error: 'no_version' } } };
const v = r.version;
const clean = (s) => String(s).replace(/[^A-Za-z0-9 ._()-]/g, '');
const target = [v.employer, v.advertiser].map((s) => (typeof s === 'string' ? clean(s).trim() : '')).find((s) => s) || 'Job';
const person = clean((v.cv && typeof v.cv.name === 'string' ? v.cv.name : '') || '').trim() || 'CV';
const kind = req.doc === 'cv' ? 'CV' : 'Cover letter';
let base = clean(`${person} - ${kind} - ${target}`).replace(/^[ .]+/, '').slice(0, 100).replace(/[ .]+$/, '');
if (!base) base = 'Document';
const file = `${base}.${req.format}`;
const type = req.format === 'pdf' ? 'application/pdf' : 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
return { json: {
  render: true,
  body: { templateId: v.templateId, doc: req.doc, format: req.format, cv: v.cv, coverLetter: req.doc === 'cover_letter' ? v.coverLetter : null },
  disposition: `attachment; filename="${file}"; filename*=UTF-8''${encodeURIComponent(file).replace(/[()]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase())}`,
  contentType: type,
} };
